"""Aggregate evidence with explicit current/replayed/historical scopes."""
import hashlib,json,pathlib,datetime
ROOT=pathlib.Path(__file__).resolve().parents[2];QA=ROOT/'qa/release-1.6.0';MODELS=ROOT/'web/analysis/models'
def read(name):return json.loads((QA/name).read_text())
def sha(path):return hashlib.sha256(pathlib.Path(path).read_bytes()).hexdigest()
required=['quality-studio-capture.json','quality-final-capture.json','separator-verification.json','vocal-detail-candidate-verification.json','public-analysis-cancel-verification.json']
receipts={name:read(name) for name in required}
for name,r in receipts.items():assert r.get('passed') is True,name
# Current processing-source receipts must bind their exact production files.
for name in ['separator-verification.json','vocal-detail-candidate-verification.json','public-analysis-cancel-verification.json','quality-final-capture.json']:
 for p,digest in receipts[name].get('source_hashes',{}).items():
  if p.startswith('web/'):
   assert (ROOT/p).exists(),f'{name}: missing {p}'
   assert sha(ROOT/p)==digest,f'{name}: stale {p}'
tracks=['nightowl','stella','meaxic','grunge','falcon','sdrnr'];initial=[]
for track in tracks:
 for variant in ['mix','instrumental','controlled']:
  name=f'{track}-{variant}';m=read(f'quality-studio-{name}.json');assert m['analysisVersion']==5;assert m['vocals']['sourceSeparated'];assert m['engine']['quality']=='precision';assert m['separation']['modelId']=='uvr-mdx-net-voc-ft';assert m['bassAnalysis']['source']=='separated-accompaniment'
  initial.append({'track':name,'file':f'quality-studio-{name}.json','seconds':m['captureSeconds'],'beats':len(m['beats']),'bassNotes':len(m['bassNotes']),'articulations':len(m['vocals']['accents'])})
weak=read('quality-final-nightowl-controlled.json');assert len(weak['vocals']['phrases'])==2;assert len(weak['vocals']['accents'])==7;assert weak['vocals']['notes']==[];assert weak['vocals']['presence']=='uncertain'
replayed=read('detail-candidate-nightowl-controlled.json')['vocals']
for key in ['phrases','accents','notes','envelope','pitchContour']:assert weak['vocals'].get(key)==replayed.get(key),f'Final full-worker/replay disagree on{key}'
comparison=read('musical-detail-comparison.json');assert comparison['complete'];final=comparison['aggregates'];assert final['final_detail-mix']['tracksWithVoiceCues']==6;assert final['final_detail-controlled']['tracksWithVoiceCues']==6;assert final['final_detail-instrumental']['tracksWithVoiceCues']==0;assert final['final_detail-instrumental']['accents']==0
separator=read('separator-quality-comparison.json');seam=[r for r in separator['results'] if r['track']=='seam-mix'];assert len(seam)==1;assert seam[0]['lengthMatch'];assert seam[0]['sourceWindowEnvelopeLagMs']==[0.0]*4
model_manifest=json.loads((MODELS/'model-manifest.json').read_text());models={}
for m in list(model_manifest.values())+[json.loads((MODELS/'vocal-model.json').read_text()),json.loads((MODELS/'separator-mdx-model.json').read_text())]:
 path=MODELS/m['file'];assert sha(path)==m['sha256'];assert path.stat().st_size==m['bytes'];models[path.name]={'bytes':path.stat().st_size,'sha256':sha(path),'model':m.get('model',m.get('name')),'id':m['id'],'license':m['license'],'source':m.get('source',m.get('origin'))}
paths=['web/analysis/worker.js','web/analysis/analyzer.js','web/analysis/stem-cache.js','web/analysis/wav-reader.js','web/analysis/dsp.js','web/analysis/bass-notes.js','web/analysis/vocal.js','web/analysis/vocal-detail.js','web/analysis/separator-mdx.js','web/analysis/models/features.json','web/analysis/models/model-manifest.json','web/analysis/models/vocal-model.json','web/analysis/models/vocal-frontend.json','web/analysis/models/separator-mdx-model.json']+[str((MODELS/n).relative_to(ROOT)) for n in models]
evidence=required+['quality-final-nightowl-controlled.json','vocal-detail-candidate-verification.json','musical-detail-comparison.json','separator-quality-comparison.json','musdb-fixture-provenance.json','seam-fixture-provenance.json','user-glass-fixture-provenance.json']
result={'release':'1.6.0','analysisVersion':5,'passed':True,'errors':[],'createdAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'models':models,'source_hashes':{p:sha(ROOT/p) for p in paths},'evidence_hashes':{str((QA/n).relative_to(ROOT)):sha(QA/n) for n in set(evidence)},'scope':{'initialPublicWorkerPass':'18actual precision-model public MusicAnalyzer calls. Early cases precede the final weak-voice fallback; original outputs are retained unchanged as audit evidence.','finalDetailReplay':'All18 actual MDX-estimated sources replayed through the exact final production float downsampler, actual isolated-source Frame-MN10 inference, and final vocal-detail code. Original studio stems are used only by independent scoring, never substituted into production.','finalPublicWorkerRegression':'The previously missed NightOwl controlled vocal is rerun through the complete final public worker. Its phrase, accent, envelope, note, and contour arrays exactly match the final replay.','lifecycle':'Three public-worker cancellations after writable OPFS cache creation and loaded MDX separation; AbortError and eventual namespace removal verified on actual Chromium OPFS.','historicalRhythm':'Existing unchanged Beat This! model/frontend reference evidence is retained in prior releases. Current precision-model rhythm inference also ran as part of all18 public-worker cases.','integration':'The separate integration-verification.json binds actual file-picker import, current compiler, WebGL preview, saved-project restoration and exported ZIP on two real reference songs and a64second original-user-audio prefix.'},'initialPublicWorkerCases':initial,'finalWeakVoiceRegression':{'source':'quality-final-nightowl-controlled.json','phrases':weak['vocals']['phrases'],'articulations':len(weak['vocals']['accents']),'pitchNotes':len(weak['vocals']['notes']),'presence':weak['vocals']['presence'],'finalReplayExact':True},'musicalDetail':comparison['aggregates'],'separatorQuality':separator['summary'],'sourceClockRegression':seam[0],'cancellationTrials':receipts['public-analysis-cancel-verification.json']['results'],'selection':{'model':'UVR MDX-Net Voc FT with two-pass polarity ensemble and50%overlap','basis':'Highest mean SI-SDR and plain SDR among the measured positive candidates. Beats Spleeter on each of six positive excerpts. Four-shift Demucs and a fixed equal blend were also measured.','tradeoff':'The fixed MDX/Demucs blend improves the hard Falcon excerpt and mean envelope correlation, but reduces four other positive SI-SDRs; no universal winner is claimed. Selection prioritizes measured separation quality, not speed.','physicalDeviceVerified':False},'limitations':['These are six short excerpts and controlled remixes, not a representative or verified held-out professional benchmark. Model training overlap may exist.','Original-stem RMS is an acoustic reference, not annotated lyrics, syllables, every pitch, or human-perceived choreography quality.','The new app responds to uncertain source-led voice conservatively; NightOwl remains uncertain singing, despite recovering actual source articulation.','Voice entry/release estimates can remain early or late. The40ms controlled-window scoring tolerance must not be described as universal40ms accuracy.','MDX remains imperfect on the hard Falcon excerpt. Estimated stem audio can contain instrument bleed, reverb and residual signal in silence.','Bass notes come from separated accompaniment, not a separately isolated bass instrument. Lead and backing singers share one vocal source.','The preview and music timing have no physical phone/vehicle validation. These tests cannot establish exact Tesla mechanical movement timing or photometric brightness.']}
(QA/'analysis-verification.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS analysis aggregate:',len(initial),'public-worker cases,18final source replays, final weak-voice regression,3public cancellation trials,5bundled model graphs')
